61			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":"1","fee":0,"charged":1}]}`,                  // 字符串金额
62			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1.5,"fee":0,"charged":1}]}`,                  // 小数
63			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1e3,"fee":0,"charged":1}]}`,                  // 科学计数
64			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":true,"fee":0,"charged":1}]}`,                 // 布尔
65			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":null,"fee":0,"charged":1}]}`,                 // null
66			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":9223372036854775808,"fee":0,"charged":1}]}`,  // 上越界
67			`{"entries":[{"kind":"payment","id":"x","account":"a","asset":"z","amount":1,"fee":0,"charged":-9223372036854775809}]}`, // 下越界
68			`{"entries":"x"}`, // 类型不符
69		}
70		for i, in := range bad {
71			if _, err := ParseReconcileRequest([]byte(in)); err == nil || KindOf(err) != ErrInvalid {
72				t.Fatalf("case %d must be invalid_parameter, got %v: %s", i, err, in)
