538	// TestReconcileConcurrentWithWriters 在并发付款/退款压力下反复对账，
539	// 每份报告都必须自洽：max seq 与记录条数一致，合计可由逐笔重算得到。
540	func TestReconcileConcurrentWithWriters(t *testing.T) {
541		path := newTestLedger(t, []BalanceInit{
542			{Account: "aa", Asset: "usdc", Balance: math.MaxInt64},
543		})
544		l := openOrFail(t, path)
545	
546		stop := make(chan struct{})
547		var wg sync.WaitGroup
548	
549		// 写入方：不断用新编号提交 1 美元付款并退款其中一部分。
550		wg.Add(1)
551		go func() {
552			defer wg.Done()
553			for i := 0; ; i++ {
554				select {
555				case <-stop:
556					return
557				default:
558				}
559				id := "p-" + strconv.Itoa(i)
560				res, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{{
561					ID: id, Account: "aa", Asset: "usdc", Amount: i64p(1), State: "pending",
562				}}})
563				if err != nil {
564					t.Errorf("submit: %v", err)
565					return
566				}
567				if res.Results[0].Status == StatusSettled && i%3 == 0 {
568					_, _ = l.Refund(RefundBatch{Refunds: []RefundRequest{{
569						ID: "r-" + strconv.Itoa(i), SettlementID: id, Reason: "x",
570					}}})
571				}
572			}
573		}()
574	
575		// 对账方：空列表报告（全部缺失）必须始终是某个完整状态的一致快照。
576		for i := 0; i < 200; i++ {
577			rep, err := l.ReconcileFlow(nil)
578			if err != nil {
579				t.Fatalf("reconcile: %v", err)
580			}
581			if int64(len(rep.MissingPayments)) != rep.MaxPaymentSeq {
582				t.Fatalf("payments %d != max seq %d", len(rep.MissingPayments), rep.MaxPaymentSeq)
583			}
584			if int64(len(rep.MissingRefunds)) != rep.MaxRefundSeq {
585				t.Fatalf("refunds %d != max seq %d", len(rep.MissingRefunds), rep.MaxRefundSeq)
586			}
587			// 账本侧净扣款 = 成功付款数 - 成功退款数。
588			var net int64
589			for _, row := range rep.Totals.Ledger {
590				n := new(big.Int)
591				if _, ok := n.SetString(row.NetCharged, 10); !ok {
592					t.Fatalf("bad net %q", row.NetCharged)
593				}
594				net = n.Int64()
595			}
596			if net != rep.MaxPaymentSeq-rep.MaxRefundSeq {
597				t.Fatalf("net=%d want %d", net, rep.MaxPaymentSeq-rep.MaxRefundSeq)
598			}
599		}
600		close(stop)
601		wg.Wait()
602	}
