220			}
221		}
222		// 关联：p1 关联 r1；p2 仅在 r2 成功时关联 r2，失败结局下不得出现退款关联。
223		assertRefUntouched(t, *rep.Results[0].Record, wantP1Ref, "p1 record")
224		assertRefUntouched(t, *rep.Results[1].Record, wantP2Ref, "p2 record")
225		assertRefUntouched(t, *rep.Results[2].Record, wantR1Ref, "r1 record")
226		if failSecond {
227			// 失败的 r2 不能被算成成功记录：missing_in_ledger 且不携带账本记录。
228			if rep.Results[3].Record != nil {
229				t.Fatalf("failed r2 must not carry a ledger record: %+v", rep.Results[3].Record)
230			}
231		} else {
232			assertRefUntouched(t, *rep.Results[3].Record, wantR2Ref, "r2 record")
233		}
234	
235		// 两种结局下账本缺失列表都为空：流水完整覆盖了入选的成功记录。
236		if len(rep.MissingPayments) != 0 {
237			t.Fatalf("missing payments=%+v want empty", rep.MissingPayments)
238		}
239		if len(rep.MissingRefunds) != 0 {
240			t.Fatalf("missing refunds=%+v want empty", rep.MissingRefunds)
241		}
242	
243		// 最大成功序号：付款恒为 2；退款只计成功项（2 或 1），失败退款不占序号。
244		if rep.MaxPaymentSeq != 2 || rep.MaxRefundSeq != wantMaxRefundSeq {
245			t.Fatalf("max seqs=%d/%d want 2/%d", rep.MaxPaymentSeq, rep.MaxRefundSeq, wantMaxRefundSeq)
246		}
247		if rep.PaymentAfter != 0 || rep.PaymentThrough != 2 ||
248			rep.RefundAfter != 0 || rep.RefundThrough != wantMaxRefundSeq {
249			t.Fatalf("full-reconcile bounds=%d,%d,%d,%d want 0,2,0,%d",
250				rep.PaymentAfter, rep.PaymentThrough, rep.RefundAfter, rep.RefundThrough, wantMaxRefundSeq)
251		}
252	
253		// 金额汇总（十进制字符串）：账本侧按完整账本，流水侧按输入流水。
254		if got := findTotalRow(t, rep.Totals.Ledger, acct, asset); got != wantLedgerRow {
255			t.Fatalf("ledger totals:\n got %+v\nwant %+v", got, wantLedgerRow)
256		}
257		if len(rep.Totals.Ledger) != 1 {
258			t.Fatalf("ledger totals rows=%d want 1: %+v", len(rep.Totals.Ledger), rep.Totals.Ledger)
259		}
260		if got := findTotalRow(t, rep.Totals.Flow, acct, asset); got != wantFlowRow {
261			t.Fatalf("flow totals:\n got %+v\nwant %+v", got, wantFlowRow)
262		}
263		if len(rep.Totals.Flow) != 1 {
264			t.Fatalf("flow totals rows=%d want 1: %+v", len(rep.Totals.Flow), rep.Totals.Flow)
265		}
266		if !reflect.DeepEqual(rep.NetDiff, []ReconNetDiff{wantNetDiff}) {
267			t.Fatalf("net diff:\n got %+v\nwant %+v", rep.NetDiff, []ReconNetDiff{wantNetDiff})
268		}
269	
270		// ---- 对账只读：不新增退款、不改变余额或账本文件 ----
271		snap := mustQuery(t, lRecon)
272		if !reflect.DeepEqual(snap.Refunds, wantRefunds) {
273			t.Fatalf("refunds after reconcile:\n got %+v\nwant %+v (reconcile must not add refunds)", snap.Refunds, wantRefunds)
274		}
275		if len(snap.Settlements) != 2 {
276			t.Fatalf("settlements after reconcile=%d want 2", len(snap.Settlements))
277		}
278		if bal, _ := lRecon.Balance(acct, asset); bal != wantBalance {
279			t.Fatalf("balance after reconcile=%d want %d (reconcile must not move balances)", bal, wantBalance)
280		}
281	
282		// 账本文件不被对账改写：再对账一次，文件字节与报告都保持不变。
283		before, err := os.ReadFile(path)
284		if err != nil {
285			t.Fatal(err)
286		}
287		again, err := lRecon.ReconcileFlow(entries)
288		if err != nil {
289			t.Fatalf("re-reconcile: %v", err)
290		}
291		if !reflect.DeepEqual(again, rep) {
292			t.Fatalf("re-reconcile not deterministic:\n first %+v\nagain %+v", rep, again)
293		}
294		after, err := os.ReadFile(path)
295		if err != nil {
296			t.Fatal(err)
297		}
298		if !bytes.Equal(before, after) {
299			t.Fatalf("ledger file rewritten by reconcile:\nbefore=%s\nafter =%s", before, after)
300		}
301	}
302	
303	// TestReconcileWaitsForInFlightRefundBatchBothRefunded：两笔退款都成功
304	// （余额回到 1000）。与退款批次并发发起的全量对账必须等整批结束：四条流水
305	// 全部 matched，p1、p2 分别关联 r1、r2，付款与退款最大成功序号均为 2，
306	// 两侧扣款/退款合计均为 "801"，净扣款与净差额均为 "0"。
307	func TestReconcileWaitsForInFlightRefundBatchBothRefunded(t *testing.T) {
308		runReconcileDuringRefundInterleave(t, false)
309	}
310	
311	// TestReconcileWaitsForInFlightRefundBatchSecondSaveFails：r1 成功、r2 保存失败。
312	// 退款批次保留 r1、r2 报 storage_error、余额 700；并发对账基于该完整状态：
313	// 前三条流水 matched，r2 为 missing_in_ledger；p1 关联 r1，p2 无退款关联，
314	// 退款最大成功序号为 1；账本侧退款合计 "501"、净扣款 "300"，流水侧净扣款
315	// 仍为 "0"，净差额 "-300"。失败的 r2 不被算成成功记录。
316	func TestReconcileWaitsForInFlightRefundBatchSecondSaveFails(t *testing.T) {
317		runReconcileDuringRefundInterleave(t, true)
318	}
