1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"reflect"
8		"testing"
9	)
10	
11	// 本文件为离线对账报告（ReconcileFlow / ReconcileFlowRanged 返回的 *ReconReport）
12	// 与真实账本之间的独立性提供回归保障。Go 调用者拿到全量或按成功序号限定范围的
13	// 报告后，可能修改其中的记录详情、差异说明和重复位置供自己继续处理；本文件锁定：
14	//
15	//  1. 结果之间彼此独立：同一付款/退款编号在输入中多次出现时，范围内重复组逐项
16	//     返回，整组各项都携带完整输入位置及对应成功记录的独立副本；调用者改动其中
17	//     一项的编号、账户、金额、付款与退款关联或位置列表，其他项保留原内容。
18	//     付款编号与退款编号各自独立，同名编号编辑一类结果不能影响另一类。
19	//  2. 范围外优先且彼此独立：记录在范围外时继续优先报告 out_of_scope 并保留关联
20	//     信息；同一范围外记录被多条流水引用时，编辑其中一条结果不连带改变其他条目。
21	//  3. 报告与账本空间独立：调用者改动逐项详情、字段差异、缺失记录和金额汇总后，
22	//     查询到的余额与成功历史保持原样；用原流水与原范围重新对账，仍得到依据真实
23	//     账本计算的状态、关联、位置及汇总，不沿用调用者改过的数据。
24	//  4. 只读：对账与编辑返回值都不改写账本文件，已有付款、退款行为不受影响。
25	//  5. 时效独立：取得报告后账本再发生付款或退款，新报告反映真实变化，旧报告仍保留
26	//     取得时的记录、缺失列表、金额汇总、最大成功序号与实际范围；原先未退款的付款
27	//     后来退款时，旧报告付款不得自动出现新退款关联，新报告必须带上该关联，即使
28	//     关联退款不在选定范围内。空流水正常返回的缺失报告遵守同样的独立性。
29	//
30	// 核对规则、报告格式与 ReconcileFlow/ReconcileFlowRanged 公开入口均不在本文件变更。
31	
32	// reconBounds 是构造核对范围的便捷函数：after < seq <= through。
33	func reconBounds(pa, pt, ra, rt int64) ReconcileBounds {
34		return ReconcileBounds{
35			PaymentAfter: &pa, PaymentThrough: &pt,
36			RefundAfter: &ra, RefundThrough: &rt,
37		}
38	}
39	
40	// mustReconcile 执行一次对账，失败即终止用例。
41	func mustReconcile(t *testing.T, l *Ledger, entries []FlowEntry, bounds ReconcileBounds) *ReconReport {
42		t.Helper()
43		rep, err := l.ReconcileFlowRanged(entries, bounds)
44		if err != nil {
45			t.Fatalf("ReconcileFlowRanged: %v", err)
46		}
47		return rep
48	}
49	
50	// cloneReconReport 深拷贝一份对账报告，作为“调用者取得时”的冻结基线：
51	// ReconRecordRef 是指针字段，逐项结果必须连同其 *Record 一起复制，否则后续比较
52	// 会被调用者对自己那份报告的编辑污染。
53	func cloneReconReport(r *ReconReport) *ReconReport {
54		b, err := json.Marshal(r)
55		if err != nil {
56			panic(err)
57		}
58		var cp ReconReport
59		if err := json.Unmarshal(b, &cp); err != nil {
60			panic(err)
61		}
62		return &cp
63	}
64	
65	// corruptReconResult 像调用者为自己继续处理所做的那样，破坏性改写一条逐项结果：
66	// 顶层编号/状态/位置列表、差异说明，以及命中记录的编号、账户、资产、金额、
67	// 手续费、扣款总额、序号、原付款编号与退款关联一律换成伪造值。
68	func corruptReconResult(r *ReconResult) {
69		r.ID = "HACK-ID"
70		r.Kind = "forged-kind"
71		r.Status = "forged-status"
72		if r.Positions != nil {
73			r.Positions[0] = 4242
74			r.Positions = append(r.Positions, 999)
75		} else {
76			r.Positions = []int{7, 7}
77		}
78		if r.Diffs != nil {
79			r.Diffs[0] = FieldDiff{Field: "forged", Ledger: "HACK-L", Flow: "HACK-F"}
80		} else {
81			r.Diffs = []FieldDiff{{Field: "injected", Ledger: "x", Flow: "y"}}
82		}
83		if r.Record == nil {
84			return
85		}
86		r.Record.Kind = "forged-kind"
87		r.Record.ID = "HACK-REC"
88		r.Record.Account = "zz"
89		r.Record.Asset = "btc"
90		r.Record.Amount = 1
91		r.Record.Fee = 1
92		r.Record.Charged = 2
93		r.Record.Seq = 77
94		r.Record.SettlementID = "p-fake"
95		r.Record.RefundID = "r-fake"
96		r.Record.RefundSeq = 88
97	}
98	
99	// corruptReconRef 破坏性改写一条缺失/汇总中携带的记录引用（全部字段，含两类关联）。
100	func corruptReconRef(r *ReconRecordRef) {
101		r.Kind = "forged-kind"
102		r.ID = "HACK-MISSING"
103		r.Account = "zz"
104		r.Asset = "btc"
105		r.Amount = 11
106		r.Fee = 22
107		r.Charged = 33
108		r.Seq = 66
109		r.SettlementID = "p-fake"
110		r.RefundID = "r-fake"
111		r.RefundSeq = 55
112	}
113	
114	// corruptReconTotals 破坏性改写单侧汇总的每一行（金额换成伪造的大数字符串）。
115	func corruptReconTotals(rows []ReconTotalRow) {
116		for i := range rows {
117			rows[i].Account = "zz-" + rows[i].Account
118			rows[i].ChargedTotal = "999999"
119			rows[i].RefundedTotal = "888888"
120			rows[i].NetCharged = "111111"
121		}
122	}
123	
124	// assertReconReportDeepEqual 逐字段断言两份报告一致（含指针记录与各汇总）。
125	func assertReconReportDeepEqual(t *testing.T, got, want *ReconReport, label string) {
126		t.Helper()
127		if !reflect.DeepEqual(got, want) {
128			gj, _ := json.Marshal(got)
129			wj, _ := json.Marshal(want)
130			t.Fatalf("%s:\n got %s\nwant %s", label, gj, wj)
131		}
132	}
133	
134	// assertResultUntouched 断言一条逐项结果仍与冻结基线完全一致。
135	func assertResultUntouched(t *testing.T, got, want ReconResult, label string) {
136		t.Helper()
137		if !reflect.DeepEqual(got, want) {
138			gj, _ := json.Marshal(got)
139			wj, _ := json.Marshal(want)
140			t.Fatalf("%s:\n got %s\nwant %s", label, gj, wj)
141		}
142	}
143	
144	// assertRefUntouched 断言一条记录引用逐字段保持原值（缺失列表与命中记录共用）。
145	func assertRefUntouched(t *testing.T, got, want ReconRecordRef, label string) {
146		t.Helper()
147		if got != want {
148			t.Fatalf("%s:\n got %+v\nwant %+v", label, got, want)
149		}
150	}
151	
152	// ---- 1. 范围内重复组：逐项独立副本 ----
153	
154	// TestReconcileDuplicateResultsAreIndependent 锁定同一付款编号在输入中多次出现时，
155	// 范围内重复组逐项返回：每项都携带完整输入位置 [0,1,2] 与同一条成功记录的独立
156	// 副本；调用者逐项破坏改写其中一条（编号、账户、金额、关联、位置列表），其余
157	// 尚未被改的项必须保留原来的状态、位置与记录详情。
158	func TestReconcileDuplicateResultsAreIndependent(t *testing.T) {
159		l := rangeLedger(t)
160		// 付款范围选 (0,3] 全量；p2(seq=2) 在范围内，出现三次，内容各不相同也仍是
161		// 整组重复（不判字段差异）。
162		entries := []FlowEntry{
163			flowEntry(0, "payment", "p2", "aa-1", "usdc", 2000, 6, 2006, ""),
164			flowEntry(1, "payment", "p2", "aa-1", "usdc", 999, 0, 999, ""),
165			flowEntry(2, "payment", "p2", "OTHER", "eth", 7, 7, 14, ""),
166		}
167		rep := mustReconcile(t, l, entries, reconBounds(0, 3, 0, 2))
168	
169		wantRec := ReconRecordRef{
170			Kind: "payment", ID: "p2", Account: "aa-1", Asset: "usdc",
171			Amount: 2000, Fee: 6, Charged: 2006, Seq: 2,
172			RefundID: "r2", RefundSeq: 2, // 范围内重复项仍携带该付款的退款关联
173		}
174		for i, r := range rep.Results {
175			if r.Status != ReconDuplicate {
176				t.Fatalf("result %d status=%s want duplicate", i, r.Status)
177			}
178			if !reflect.DeepEqual(r.Positions, []int{0, 1, 2}) {
179				t.Fatalf("result %d positions=%v want [0 1 2]", i, r.Positions)
180			}
181			if len(r.Diffs) != 0 {
182				t.Fatalf("duplicate must carry no diffs, result %d: %+v", i, r.Diffs)
183			}
184			if r.Record == nil {
185				t.Fatalf("result %d must carry the ledger record", i)
186			}
187			assertRefUntouched(t, *r.Record, wantRec, "duplicate record")
188		}
189	
190		// 三个命中记录必须是各自独立的分配，两两不共享。
191		for i := 0; i < len(rep.Results); i++ {
192			for j := i + 1; j < len(rep.Results); j++ {
193				if rep.Results[i].Record == rep.Results[j].Record {
194					t.Fatalf("duplicate results %d and %d share one *ReconRecordRef", i, j)
195				}
196			}
197		}
198		// 位置列表也必须是每条结果各自的底层数组。
199		if &rep.Results[0].Positions[0] == &rep.Results[1].Positions[0] {
200			t.Fatal("duplicate results share the positions backing array")
201		}
202	
203		// 冻结逐项基线后逐项破坏：每改一项，其余尚未被改的项保持原状态/位置/记录。
204		saved := make([]ReconResult, len(rep.Results))
205		copy(saved, rep.Results)
206		corrupted := map[int]bool{}
207		for i := range rep.Results {
208			corruptReconResult(&rep.Results[i])
209			corrupted[i] = true
210			for j := range rep.Results {
211				if corrupted[j] {
212					continue
213				}
214				assertResultUntouched(t, rep.Results[j], saved[j],
215					"other duplicate entry changed after editing one")
216			}
217		}
218	}
219	
220	// TestReconcileDuplicateSameIDPaymentAndRefundStayIndependent 付款编号与退款编号
221	// 即使相同也仍是两类独立记录：同名重复组分别按付款、退款核对；编辑付款类结果的
222	// 记录编号/账户/金额/关联/位置，不能改变退款类各项，反之亦然。
223	func TestReconcileDuplicateSameIDPaymentAndRefundStayIndependent(t *testing.T) {
224		l := rangeLedger(t)
225		// 编号 "x1"：账本无付款 x1（重复组，无命中记录）；退款侧没有 x1 也无记录。
226		// 同时构造命中记录的同名编号：用 "r1" —— 付款 r1 账本无此付款（无记录），
227		// 退款 r1 命中 seq=1（重复两次）。这样同名编号横跨两类且一类带记录。
228		entries := []FlowEntry{
229			flowEntry(0, "payment", "r1", "aa-1", "usdc", 5, 0, 5, ""),
230			flowEntry(1, "payment", "r1", "aa-1", "usdc", 6, 0, 6, ""),
231			flowEntry(2, "refund", "r1", "aa-1", "usdc", 1000, 3, 1003, "p1"),
232			flowEntry(3, "refund", "r1", "aa-1", "usdc", 1000, 3, 1003, "p1"),
233		}
234		rep := mustReconcile(t, l, entries, reconBounds(0, 3, 0, 2))
235	
236		wantStatus := []string{ReconDuplicate, ReconDuplicate, ReconDuplicate, ReconDuplicate}
237		for i, s := range wantStatus {
238			if rep.Results[i].Status != s {
239				t.Fatalf("result %d status=%s want %s", i, rep.Results[i].Status, s)
240			}
241		}
242		// 付款 r1 在付款空间不存在 -> 无记录；退款 r1 命中 -> 带退款记录与原付款 p1。
243		for _, i := range []int{0, 1} {
244			if rep.Results[i].Record != nil {
245				t.Fatalf("payment r1 duplicate must have no record, result %d: %+v", i, rep.Results[i].Record)
246			}
247			if !reflect.DeepEqual(rep.Results[i].Positions, []int{0, 1}) {
248				t.Fatalf("payment r1 positions=%v want [0 1]", rep.Results[i].Positions)
249			}
250		}
251		wantRefundRec := ReconRecordRef{
252			Kind: "refund", ID: "r1", Account: "aa-1", Asset: "usdc",
253			Amount: 1000, Fee: 3, Charged: 1003, Seq: 1, SettlementID: "p1",
254		}
255		for _, i := range []int{2, 3} {
256			if !reflect.DeepEqual(rep.Results[i].Positions, []int{2, 3}) {
257				t.Fatalf("refund r1 positions=%v want [2 3]", rep.Results[i].Positions)
258			}
259			if rep.Results[i].Record == nil {
260				t.Fatalf("refund r1 duplicate must carry record, result %d", i)
261			}
262			assertRefUntouched(t, *rep.Results[i].Record, wantRefundRec, "refund r1 record")
263		}
264	
265		saved := make([]ReconResult, len(rep.Results))
266		copy(saved, rep.Results)
267	
268		// 编辑付款类两条结果（含其空记录情形与位置列表）：退款类各项保持原值。
